raw_sql:
SELECT AVG(hourly_cost_usd) AS avg_local_model_cost_usd
FROM support.agents
WHERE team = 'support';

SELECT COUNT(*) AS total_escalations
FROM marts.fct_outcomes
WHERE escalated = TRUE;

SELECT COUNT(*) AS recent_tickets
FROM support.tickets
WHERE opened_at >= NOW() - INTERVAL '1 day';

SELECT COUNT(*)
FROM support.tickets
WHERE status = 'resolved' AND opened_at >= NOW() - INTERVAL '1 day';

SELECT hourly_cost_usd
FROM support.agents
WHERE display_name = 'Farhana Khan';

SELECT accuracy
FROM marts.mart_cost_per_outcome
WHERE split = 'test';

SELECT AVG(cache_hit_rate) AS average_cache_hit_rate
FROM marts.mart_cost_per_outcome
WHERE arm = 'cache_on';

SELECT AVG(f.latency_ms) AS avg_latency_ms
FROM marts.fct_requests f
WHERE f.split = 'test' AND f.provider = 'vllm';

SELECT AVG(input_tokens + output_tokens) AS avg_total_tokens
FROM marts.fct_requests
WHERE provider = 'vllm' AND split = 'test';

SELECT email
FROM support.agents
WHERE team = 'billing';

SELECT display_name, email
FROM support.agents
WHERE is_active = true;

SELECT COUNT(*) AS total_decisions
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';

SELECT monthly_budget_usd
FROM marts.dim_tenant
WHERE display_name = 'billing';

SELECT prompt_version, n_fewshot
FROM marts.dim_prompt_version
ORDER BY prompt_version;

SELECT COUNT(*) AS cache_hits
FROM marts.fct_requests
WHERE cache_status = 'HIT';

SELECT COUNT(*) AS high_priority_tickets
FROM support.tickets
WHERE tenant_id = 'support' AND priority = 'high';

SELECT COUNT(*) 
FROM support.agents 
WHERE team = 'billing';

SELECT COUNT(*) AS tfidf_baseline_decisions
FROM marts.fct_outcomes
WHERE prompt_version = 'none' AND split = 'tune';

SELECT COUNT(DISTINCT gold_label) AS distinct_gold_intents
FROM marts.fct_outcomes
WHERE split = 'test';

SELECT COUNT(*)
FROM support.tickets
WHERE tenant_id = 'billing' AND channel = 'chat';

SELECT COUNT(*) AS open_tickets
FROM support.tickets
WHERE tenant_id = 'support' AND status = 'open';

SELECT MIN(opened_at) AS earliest_opened_at
FROM support.tickets
WHERE tenant_id = 'sales';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT COUNT(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6;

SELECT COUNT(*) AS resolved_tickets
FROM support.tickets
WHERE status = 'resolved';

SELECT AVG(accuracy) AS local_model_accuracy
FROM marts.mart_cost_per_outcome
WHERE setup = 'B_local';

SELECT SUM(total_cost_usd) AS total_spent
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND split = 'test';

SELECT COUNT(*) AS reopened_tickets
FROM support.ticket_events
WHERE event_type = 'reopened';

SELECT AVG(hourly_cost_usd) AS average_hourly_cost_usd
FROM support.agents
WHERE is_active = TRUE;

SELECT COUNT(*)
FROM support.tickets
WHERE assigned_agent_id IS NULL AND status = 'resolved';
